// Claude Code JSONL session parser (JS port of the Python claude-code-to-dsh).
// Pure node stdlib; no dependencies. Runs in the DSH host process.

import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import os from "node:os";
import path from "node:path";

const SKIP_MARKERS = [
  "caveat",
  "ide_opened_file",
  "command-message",
  "command-name",
  "the user opened",
  "generated by the user while running local commands",
  "may or may not be related",
  "<mcp-",
  "session started",
];

const FILE_TOOL_OPS = {
  Write: "Write",
  MultiEdit: "Edit",
  Edit: "Edit",
  Read: "Read",
  NotebookEdit: "Edit",
};

export function defaultProjectsRoot() {
  return path.join(os.homedir(), ".claude", "projects");
}

export function listSessionFiles(root = defaultProjectsRoot()) {
  const found = [];
  if (!existsSync(root)) return found;
  for (const entry of readdirSync(root)) {
    const pdir = path.join(root, entry);
    let st;
    try {
      st = statSync(pdir);
    } catch {
      continue;
    }
    if (!st.isDirectory()) continue;
    for (const name of readdirSync(pdir)) {
      if (name.endsWith(".jsonl")) {
        const p = path.join(pdir, name);
        found.push({ path: p, projectKey: entry });
      }
    }
  }
  found.sort((a, b) => statSync(b.path).mtimeMs - statSync(a.path).mtimeMs);
  return found;
}

function clean(text, limit = 400) {
  text = String(text).replace(/\s+/g, " ").trim();
  while (text.startsWith("<") && text.includes(">")) {
    text = text.slice(text.indexOf(">") + 1).trim();
  }
  return text.length > limit ? text.slice(0, limit) : text;
}

function extractText(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    const parts = [];
    for (const c of content) {
      if (c && typeof c === "object" && c.type === "text" && typeof c.text === "string") {
        parts.push(c.text);
      }
    }
    return parts.join(" ");
  }
  return "";
}

function isRealPrompt(text) {
  const low = String(text).toLowerCase();
  return Boolean(text) && !SKIP_MARKERS.some((m) => low.includes(m)) && !text.startsWith("<");
}

function recordFootprint(info, tool) {
  const op = FILE_TOOL_OPS[tool.name || ""];
  if (!op) return;
  const input = tool.input || {};
  const p = typeof input.file_path === "string" ? input.file_path : typeof input.path === "string" ? input.path : null;
  if (!p) return;
  const ops = info.footprints[p] || (info.footprints[p] = []);
  if (!ops.includes(op)) ops.push(op);
}

/**
 * Parse one Claude Code session JSONL. Returns a plain object with:
 * id, projectKey, projectDir (from cwd or best-effort decode), title,
 * aiTitle, firstUserPrompt, summaries[], lastPrompts[], footprints{},
 * stats {user, assistant, toolCalls, errorResults}, tail {lastUserMessages,
 * lastAssistantText}, timeRange {firstTs, lastTs}, localCommandMode,
 * sizeBytes, mtimeMs.
 */
export function parseSession(filePath, projectKey, opts = {}) {
  const name = path.basename(filePath);
  const sessionId = name.endsWith(".jsonl") ? name.slice(0, -6) : name;
  const st = statSync(filePath);
  const info = {
    id: sessionId,
    rawPath: filePath,
    projectKey: projectKey || path.basename(path.dirname(filePath)),
    cwd: null,
    aiTitles: [],
    summaries: [],
    lastPrompts: [],
    footprints: {},
    userMessages: 0,
    assistantMessages: 0,
    toolCalls: 0,
    errorResults: 0,
    lastUserMessages: [],
    lastAssistantText: null,
    firstTs: null,
    lastTs: null,
    localCommandMode: false,
    sizeBytes: st.size,
    mtimeMs: st.mtimeMs,
  };

  const lines = readFileSync(filePath, "utf8").split("\n");
  const maxLines = opts.maxLines || Infinity;
  const firstUserTexts = [];

  for (let i = 0; i < lines.length && i < maxLines; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      continue;
    }
    if (!obj || typeof obj !== "object") continue;

    if (info.cwd === null && typeof obj.cwd === "string" && obj.cwd.trim()) {
      info.cwd = path.normalize(obj.cwd);
    }

    let ts = obj.timestamp;
    if (typeof ts === "string") {
      const s = ts.endsWith("Z") ? ts.slice(0, -1) : ts;
      const ms = Date.parse(s + (s.includes(".") ? "" : ".000Z"));
      ts = isNaN(ms) ? null : ms / 1000;
    } else if (typeof ts === "number") {
      ts = ts;
    } else {
      ts = null;
    }
    if (ts !== null) {
      if (info.firstTs === null || ts < info.firstTs) info.firstTs = ts;
      if (info.lastTs === null || ts > info.lastTs) info.lastTs = ts;
    }

    const t = obj.type;

    if (t === "ai-title" && typeof obj.aiTitle === "string" && obj.aiTitle.trim()) {
      info.aiTitles.push(obj.aiTitle.trim());
    } else if (t === "summary" && typeof obj.summary === "string" && obj.summary.trim()) {
      info.summaries.push({ text: obj.summary.trim(), timestamp: ts });
    } else if (t === "last-prompt" && typeof obj.lastPrompt === "string" && obj.lastPrompt.trim()) {
      info.lastPrompts.push(obj.lastPrompt.trim());
      if (info.lastPrompts.length > 3) info.lastPrompts.shift();
    } else if (t === "user") {
      info.userMessages++;
      const content = (obj.message || {}).content;
      if (Array.isArray(content)) {
        for (const c of content) {
          if (c && c.type === "tool_result" && c.is_error) info.errorResults++;
        }
      }
      const text = clean(extractText(content), 2000);
      if (text) {
        if (firstUserTexts.length < 10) firstUserTexts.push(text);
        if (info.firstUserPrompt === undefined && isRealPrompt(text)) {
          info.firstUserPrompt = text;
        }
        info.lastUserMessages.push(text);
        if (info.lastUserMessages.length > 3) info.lastUserMessages.shift();
      }
    } else if (t === "assistant") {
      info.assistantMessages++;
      const content = (obj.message || {}).content;
      const text = extractText(content);
      if (text.trim()) info.lastAssistantText = clean(text, 1500);
      if (Array.isArray(content)) {
        for (const c of content) {
          if (c && c.type === "tool_use") {
            info.toolCalls++;
            recordFootprint(info, c);
          }
        }
      }
    } else if (t === "tool_use") {
      info.toolCalls++;
      recordFootprint(info, obj);
    } else if (t === "tool_result") {
      if (obj.is_error) info.errorResults++;
    }
  }

  // dedupe tail user messages
  const seen = new Set();
  info.lastUserMessages = info.lastUserMessages.filter((m) => {
    if (seen.has(m)) return false;
    seen.add(m);
    return true;
  });

  if (firstUserTexts.length > 0) {
    const injected = firstUserTexts.filter((t) => !isRealPrompt(t)).length;
    info.localCommandMode = injected / firstUserTexts.length >= 0.6;
  }

  info.projectDir = info.cwd || decodeProjectKey(info.projectKey);
  info.title = info.aiTitles.length
    ? clean(info.aiTitles[info.aiTitles.length - 1])
    : info.summaries.length
      ? clean(info.summaries[info.summaries.length - 1].text)
      : info.firstUserPrompt
        ? clean(info.firstUserPrompt)
        : "(无文本)";

  info.editedFiles = Object.entries(info.footprints)
    .filter(([, ops]) => ops.some((o) => o === "Write" || o === "Edit"))
    .map(([p, ops]) => ({ path: p, ops: ops.join(", ") }))
    .sort((a, b) => a.path.localeCompare(b.path));

  return info;
}

/** Best-effort decode of a Claude Code project folder key to a path. */
export function decodeProjectKey(key) {
  const segs = key.replace(/^-/, "").split("-").filter(Boolean);
  if (segs.length === 0) return key;
  const n = segs.length;
  let best = null; // [depth, path, merges]
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    const parts = [];
    let cur = segs[0];
    for (let g = 0; g < n - 1; g++) {
      if (mask & (1 << g)) cur = cur + "-" + segs[g + 1];
      else {
        parts.push(cur);
        cur = segs[g + 1];
      }
    }
    parts.push(cur);
    const cand = "/" + parts.join("/");
    if (existsSync(cand)) {
      const merges = (mask.toString(2).match(/1/g) || []).length;
      if (!best || parts.length > best[0] || (parts.length === best[0] && merges < best[2])) {
        best = [parts.length, cand, merges];
      }
    }
  }
  return best ? best[1] : "/" + segs.join("/");
}

/** Resolve a session-id prefix or jsonl path to a file. */
export function resolveSessionFile(sessionId, projectsRoot = defaultProjectsRoot()) {
  if (existsSync(sessionId)) return sessionId;
  for (const f of listSessionFiles(projectsRoot)) {
    const base = path.basename(f.path);
    if (base.startsWith(sessionId) || base.slice(0, 8) === sessionId) return f.path;
  }
  return null;
}
